        // This function extracts a value for a given key from a block of text.
        function getValue(text, key) {
            const regex = new RegExp(`^\\s*${key}:\\s*(.*?)\\s*$`, 'im');
            const match = text.match(regex);
            return match ? match[1].trim() : null;
        }

        // *** CORE LOGIC UPDATED FOR NEW FORMAT ***
        function parseData(text) {
            const data = {
                location: getValue(text, 'location') || '未知地点',
                date: getValue(text, 'date') || 'N/A',
                time: getValue(text, 'time') || '--:--',
                weather: getValue(text, 'weather') || '-',
                user: {
                    name: getValue(text.match(/\[使用者\]([\s\S]*?)\[\/使用者\]/)?.[0] || '', 'name') || 'USER',
                    title: getValue(text.match(/\[使用者\]([\s\S]*?)\[\/使用者\]/)?.[0] || '', 'title') || 'UNKNOWN'
                },
                characters: []
            };

            const charactersBlockMatch = text.match(/\[人物\]([\s\S]*?)\[\/人物\]/);
            if (charactersBlockMatch) {
                const lines = charactersBlockMatch[1].trim().split('\n');
                let currentCharacter = null;

                lines.forEach(line => {
                    line = line.trim();
                    if (!line) return; // Skip empty lines

                    const key = line.substring(0, line.indexOf(':')).trim();
                    const value = line.substring(line.indexOf(':') + 1).trim();

                    if (key === 'name') {
                        // If a new character starts, push the previous one to the array
                        if (currentCharacter) {
                            data.characters.push(currentCharacter);
                        }
                        // Start a new character object
                        currentCharacter = { name: value };
                    } else if (currentCharacter && key) {
                        // Add properties to the current character object
                        currentCharacter[key] = value;
                    }
                });

                // Push the last character object after the loop
                if (currentCharacter) {
                    data.characters.push(currentCharacter);
                }
            }
            return data;
        }

        function renderUI(data) {
            ui.userName.textContent = data.user.name;
            ui.userTitle.textContent = data.user.title;
            ui.date.textContent = data.date;
            ui.time.textContent = data.time;
            ui.weather.textContent = data.weather;
            ui.location.textContent = data.location;

            ui.characterList.innerHTML = '';
            data.characters.forEach((char, index) => {
                const tab = document.createElement('div');
                tab.className = 'p5-character-tab';
                tab.textContent = char.name;
                tab.dataset.charIndex = index;
                tab.addEventListener('click', function() {
                    document.querySelectorAll('.p5-character-tab').forEach(t => t.classList.remove('active'));
                    this.classList.add('active');
                    renderDetail(data.characters[this.dataset.charIndex]);
                });
                ui.characterList.appendChild(tab);
            });

            if (data.characters.length > 0) {
                 ui.characterList.querySelector('.p5-character-tab').click();
            } else {
                 ui.characterDetail.innerHTML = '<div class="no-character-selected">NO DATA</div>';
            }
        }

        function renderDetail(char) {
            const statusClass = (char.status === '已支配') ? 'dominated' : (char.status === '接触中') ? 'contacting' : 'untouched';
            const affinityClass = (char.affinity === '狂信') ? 'fanaticism' : (char.affinity === '协力') ? 'cooperation' : 'stranger';
            const avatarUrl = avatarMap[char.name] || 'https://i.imgur.com/placeholder.png';
            ui.characterDetail.innerHTML = `
                <div class="p5-detail-content active">
                    <div class="p5-avatar-wrapper"><img src="${avatarUrl}" alt="${char.name}" class="p5-avatar"></div>
