                    </div>
                    <div class="p5-detail-section">
                        <div class="p5-detail-title">关系 (Relation)</div><div class="p5-detail-value affinity-${affinityClass}">${char.affinity || '...'}</div>
                    </div>
                </div>`;
        }

        const rawData = dataContainer.textContent.trim();
        if (rawData) {
